	serverReady           bool
	serverAddr            string
	server                *llama.Server
	client                *llama.Client
	maxHistory            int
	maxContextMessages    int
	maxContextChars       int
	maxModelCalls         int
	maxDuration           time.Duration
	maxToolSteps          int
	maxNoProgressTurns    int
	seedResults           []workspace.ToolResult
	initialNeedsNarrowing bool
	initialBroadInspects  int
	taskLedgerPolicy      agent.TaskLedgerPolicy
	permissionPolicy      agent.ToolPermissionPolicy
	checkpointPolicy      agent.CheckpointPolicy
	completionGate        agent.CompletionGate
	runtimeBrief          workerruntime.WorkerRuntimeBrief
	onEvent               func(agent.RunEvent)
	disableTaskTool       bool
	instructionAttacher   *agent.InstructionAttacher
	doomLoopGate          func(req workspace.ToolRequest, count int) bool
	lastAssistantMessage  llama.ChatMessage
	lastAssistantReasoningContent string
	compactionPolicy      CompactionPolicy
	pendingAssistantIndex int
	// pendingAssistantMessage is the assistant message currently being
	// streamed from the server. It is visible in the history panel but
	// not yet appended to messages until the stream completes.
	pendingAssistantMessage string
}
